const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const fmt = value => value ? new Date(`${value.slice(0,10)}T12:00:00`).toLocaleDateString('el-CY') : '—';
const euro = value => value === null || value === undefined || value === '' ? '—' : Number(value).toLocaleString('el-CY',{style:'currency',currency:'EUR'});
